import React, { useCallback, useState } from 'react';
import { motion } from 'framer-motion';
import { useDropzone } from 'react-dropzone';
import { 
  Upload, 
  FileText, 
  X, 
  CheckCircle, 
  AlertCircle,
  Trash2,
  Download,
  Settings
} from 'lucide-react';
import { useFile } from '../contexts/FileContext';
import { useTheme } from '../contexts/ThemeContext';
import toast from 'react-hot-toast';

export default function FileProcessor() {
  const { files, addFiles, removeFile, selectedFiles, selectFile, isFileSelected } = useFile();
  const { isDark } = useTheme();
  const [uploadProgress, setUploadProgress] = useState<Record<string, number>>({});
  const [isUploading, setIsUploading] = useState(false);

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    setIsUploading(true);

    for (let i = 0; i < acceptedFiles.length; i++) {
      const file = acceptedFiles[i];
      const fileId = `file-${Date.now()}-${i}`;

      // Simulate upload progress
      for (let progress = 0; progress <= 100; progress += 10) {
        setUploadProgress(prev => ({ ...prev, [fileId]: progress }));
        await new Promise(resolve => setTimeout(resolve, 100));
      }

      // Add file to context
      const fileInfo = {
        id: fileId,
        name: file.name,
        size: file.size,
        type: file.type || 'application/octet-stream',
        uploadTime: new Date().toISOString(),
        path: URL.createObjectURL(file),
      };

      addFiles([fileInfo]);
      delete uploadProgress[fileId];
    }

    setIsUploading(false);
    toast.success(`${acceptedFiles.length} files uploaded successfully!`);
  }, [addFiles]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'application/vnd.openxmlformats-officedocument.presentationml.presentation': ['.pptx'],
      'text/csv': ['.csv'],
      'text/plain': ['.txt'],
      'image/*': ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.webp'],
      'video/*': ['.mp4', '.avi', '.mov', '.mkv'],
      'audio/*': ['.mp3', '.wav', '.flac', '.aac'],
    },
    multiple: true,
  });

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📄';
    if (type.includes('word') || type.includes('docx')) return '📝';
    if (type.includes('sheet') || type.includes('xlsx')) return '📊';
    if (type.includes('presentation') || type.includes('pptx')) return '📈';
    if (type.includes('image')) return '🖼️';
    if (type.includes('video')) return '🎬';
    if (type.includes('audio')) return '🎵';
    return '📁';
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="space-y-6"
    >
      {/* Header */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-soft p-6 border border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
              File Processor
            </h1>
            <p className="text-gray-600 dark:text-gray-400 mt-2">
              Upload and manage your files for AI processing
            </p>
          </div>
          <div className="flex items-center space-x-4">
            {files.length > 0 && (
              <button
                onClick={() => {
                  files.forEach(file => removeFile(file.id));
                  toast.success('All files removed');
                }}
                className="flex items-center space-x-2 px-4 py-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
              >
                <Trash2 className="h-4 w-4" />
                <span>Clear All</span>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Upload Area */}
      <div
        {...getRootProps()}
        className={`
          relative border-2 border-dashed rounded-2xl p-12 text-center transition-all duration-200 cursor-pointer
          ${isDragActive
            ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
            : 'border-gray-300 dark:border-gray-600 hover:border-primary-400 dark:hover:border-primary-500'
          }
        `}
      >
        <input {...getInputProps()} />
        <div className="space-y-4">
          <div className="mx-auto w-16 h-16 bg-primary-100 dark:bg-primary-900/30 rounded-full flex items-center justify-center">
            <Upload className="h-8 w-8 text-primary-600 dark:text-primary-400" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              {isDragActive ? 'Drop your files here' : 'Drag & drop files here'}
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mt-2">
              or click to browse
            </p>
          </div>
          <div className="text-sm text-gray-500 dark:text-gray-400">
            Supports: PDF, DOCX, XLSX, PPTX, Images, Videos, Audio
          </div>
        </div>
      </div>

      {/* File List */}
      {files.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-soft p-6 border border-gray-200 dark:border-gray-700">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              Uploaded Files ({files.length})
            </h2>
            <div className="flex items-center space-x-2">
              <span className="text-sm text-gray-500 dark:text-gray-400">
                {selectedFiles.length} selected
              </span>
            </div>
          </div>

          <div className="space-y-3">
            {files.map((file, index) => (
              <motion.div
                key={file.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.3, delay: index * 0.05 }}
                className={`
                  flex items-center justify-between p-4 rounded-xl border transition-all duration-200
                  ${isFileSelected(file.id)
                    ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                    : 'border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700'
                  }
                `}
              >
                <div className="flex items-center space-x-4">
                  <input
                    type="checkbox"
                    checked={isFileSelected(file.id)}
                    onChange={() => selectFile(file.id)}
                    className="h-4 w-4 text-primary-600 rounded focus:ring-primary-500"
                  />
                  <div className="text-2xl">{getFileIcon(file.type)}</div>
                  <div>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {file.name}
                    </p>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                      {formatFileSize(file.size)} • {file.type}
                    </p>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  {uploadProgress[file.id] !== undefined && (
                    <div className="w-24">
                      <div className="bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                        <div
                          className="bg-primary-500 h-2 rounded-full transition-all duration-300"
                          style={{ width: `${uploadProgress[file.id]}%` }}
                        />
                      </div>
                    </div>
                  )}

                  <button
                    onClick={() => {
                      removeFile(file.id);
                      toast.success('File removed');
                    }}
                    className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      )}

      {/* Empty State */}
      {files.length === 0 && !isUploading && (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-soft p-12 border border-gray-200 dark:border-gray-700">
          <div className="text-center">
            <div className="mx-auto w-24 h-24 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mb-6">
              <FileText className="h-12 w-12 text-gray-400" />
            </div>
            <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              No files uploaded yet
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mb-6">
              Upload your first files to get started with AI processing
            </p>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 max-w-2xl mx-auto">
              <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="text-2xl mb-2">📄</div>
                <h4 className="font-medium text-gray-900 dark:text-white">Documents</h4>
                <p className="text-sm text-gray-600 dark:text-gray-400">PDF, DOCX, TXT</p>
              </div>
              <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="text-2xl mb-2">📊</div>
                <h4 className="font-medium text-gray-900 dark:text-white">Spreadsheets</h4>
                <p className="text-sm text-gray-600 dark:text-gray-400">XLSX, CSV</p>
              </div>
              <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="text-2xl mb-2">🖼️</div>
                <h4 className="font-medium text-gray-900 dark:text-white">Media</h4>
                <p className="text-sm text-gray-600 dark:text-gray-400">Images, Video, Audio</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Processing Actions */}
      {files.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-soft p-6 border border-gray-200 dark:border-gray-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
            Quick Actions
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <button className="flex items-center justify-center space-x-2 p-3 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors">
              <FileText className="h-4 w-4" />
              <span>Convert</span>
            </button>
            <button className="flex items-center justify-center space-x-2 p-3 bg-purple-500 text-white rounded-lg hover:bg-purple-600 transition-colors">
              <Settings className="h-4 w-4" />
              <span>Process</span>
            </button>
            <button className="flex items-center justify-center space-x-2 p-3 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors">
              <Download className="h-4 w-4" />
              <span>Download</span>
            </button>
            <button className="flex items-center justify-center space-x-2 p-3 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors">
              <Trash2 className="h-4 w-4" />
              <span>Delete</span>
            </button>
          </div>
        </div>
      )}
    </motion.div>
  );
}
